param([Parameter(Mandatory=$true)][string]$Login,[string]$RosterPath,[switch]$SharedTeamPackage,[string]$Root=(Join-Path $env:LOCALAPPDATA 'G6\RabbitMQ\g5-onboarding'))
$ErrorActionPreference='Stop';if($Login-notmatch'^g5_[a-z0-9][a-z0-9_-]{1,30}$'){throw 'Invalid G5 package recipient label.'};if($SharedTeamPackage){if($Login-cne'g5_equipo'){throw 'The shared package label is fixed to g5_equipo.'}}else{$roster=@(Import-Csv -LiteralPath $RosterPath);$entry=@($roster|Where-Object {$_.Login-ceq$Login-and$_.EstadoHomologacion-ceq'HOMOLOGADO'-and-not[string]::IsNullOrWhiteSpace($_.ReferenciaHomologacion)});if($entry.Count-ne 1-or[string]::IsNullOrWhiteSpace($entry[0].Nombre)){throw 'Package password release requires one named roster recipient with documentary homologation reference.'}}
$vault=Get-Content -Raw -LiteralPath (Join-Path $Root 'admin-vault.dpapi.json')|ConvertFrom-Json;$member=@($vault.members|Where-Object Login -CEQ $Login);if($member.Count-ne 1-or-not(Test-Path $member[0].PackagePath)){throw 'No unique encrypted package is available for this member.'};$secure=ConvertTo-SecureString $member[0].ProtectedPackagePassword;$password=[Net.NetworkCredential]::new('', $secure).Password
Set-Clipboard -Value $password;$password=$null;$secure.Dispose();Write-Output 'Package decryption password copied to the local clipboard. Deliver it only through a channel separate from the encrypted package; clear the clipboard after use.'
